  var outbox=new JdbcOutbox(source,new MinutesEventReferences(source).validators());var queue=new JdbcTaskQueue(source,new JdbcSubjectFences(source,Set.of("MEETING")),outbox,Map.of("MINUTES_GENERATE_V1",authority.minutesTaskPolicy()));var operations=new JdbcExternalOperations(queue);var permits=new JdbcModelPermitPool(operations,Map.of(ControlledMinutesProtocol.MODEL,new ModelConfiguration(ControlledMinutesProtocol.MODEL,1,1,true,ModelConfiguration.CutoffPolicy.EXPLICIT_SETTLEMENT)),(t,m,d)->{throw new IllegalStateException("No cutoff proof");});permits.configure();
