   var failure=new java.util.concurrent.atomic.AtomicReference<Throwable>();WorkerLoop.ExternalHandler handler=execution->{try{realHandler.handle(execution);}catch(Throwable error){failure.set(error);var safe=new ArrayList<String>();for(Throwable e=error;e!=null;e=e.getCause()){safe.add(e.getClass().getName());if(e instanceof ama.contract.MinutesContracts.Failure f)safe.add(f.code().name());for(var frame:e.getStackTrace())safe.add(frame.toString());}java.nio.file.Files.writeString(receipt.resolve("safe-handler-failure.json"),json.writeValueAsString(safe));throw error;}};
   var commands=new JdbcMinutesGenerationCommands(authority,prep,queue,outbox,new ama.audit.JdbcAuditAdapter(source));var accepted=commands.enqueue(actor(),meeting,"generate",4,UUID.randomUUID().toString());var result=(Map<?,?>)accepted.get("result");String task=(String)result.get("taskId");
